local MP=(getgenv and getgenv()) or _ENV or _G
local Oh={} for i=97,122 do Oh[#Oh+1]=string.char(i) end
local kj={12,15,1,4,19,20,18,9,14,7}
local Gl="" for i=1,#kj do Gl=Gl..Oh[kj[i]] end
local cT=MP and MP[Gl]
local Qb=type(cT)=="function"
if Qb then
local ON={8,15,15,11,6,21,14,3,20,9,15,14}
local Aj="" for i=1,#ON do Aj=Aj..Oh[ON[i]] end
local oj={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local Ar="" for i=1,#oj do Ar=Ar..Oh[oj[i]] end
local sX=MP[Aj]
local OF=MP[Ar]
local ep=false
if type(sX)=="function" and type(OF)=="function" then
local CN=function() return 5 end
local sv=pcall(sX,CN,function() return -777 end)
if sv and CN()==-777 then
local QL=pcall(OF,CN)
ep=(QL and CN()==5)
end
if not ep then pcall(OF,CN) end
if not ep and type(MP.math)=="table" and type(MP.math.abs)=="function" then
local sr=MP.math.abs
if sr(5)==5 then
local OB,Gh=pcall(sX,sr,function() return -777 end)
if OB and sr(5)==-777 then
local Yb=pcall(OF,sr)
ep=(Yb and sr(5)==5)
if not ep then pcall(OF,sr) MP.math.abs=(type(Gh)=="function" and Gh) or function(v) if v<0 then return -v end return v end end
end
end
end
if ep then
local GV={cT,sX,OF}
local Mj=MP.string
if type(Mj)=="table" then
GV[#GV+1]=Mj.char GV[#GV+1]=Mj.byte GV[#GV+1]=Mj.sub GV[#GV+1]=Mj.rep GV[#GV+1]=Mj.len
end
if type(MP.table)=="table" and MP.table.concat then GV[#GV+1]=MP.table.concat end
if MP.pcall then GV[#GV+1]=MP.pcall end
if type(MP.math)=="table" and MP.math.floor then GV[#GV+1]=MP.math.floor end
for Wp=1,#GV do local zt=GV[Wp] if type(zt)=="function" then pcall(OF,zt) end end
end
end
end
if not Qb then return nil end

